// New tools are created in `"draft"` status by default unless `status:
// "active"` is explicitly supplied. Draft tools are not exposed to the LLM
// during agent runs; call the activate endpoint to promote them.
// For built-in tools that support multiple instances per agent (those whose
// catalog entry has a `multi_instance_mode`), supply `name_prefix` to
// namespace the LLM-facing tool names. Requires app scope.
//
// agent: Filter results to tools belonging to these agents (`agi_...`). Omit to return tools across all agents in the app. Multiple values are OR'd.
//
// Returns: The newly created tool.
func (r *AgentAgentToolResource) Create(ctx context.Context, agent string, input AgentAgentToolCreateInput) (*AgentTool, error) {
	return fetch[*AgentTool](r.http, ctx, requestSpec{Method: "POST", Path: "/api/v1/agents/" + url.PathEscape(agent) + "/agent_tools", Body: input})
}

type AgentWorkingMemoryResource struct {
	http *HTTPClient
}

func newAgentWorkingMemoryResource(h *HTTPClient) *AgentWorkingMemoryResource {
	return &AgentWorkingMemoryResource{
		http: h,
	}
}

// List: List working memory entries for an agent
//
// Returns a paginated list of working memory entries belonging to the specified
// agent. Entries are key-value pairs the agent stores for context between
// interactions. Results are ordered by creation time descending (newest first)
// and can be filtered with a substring search against the key name.
// Requires an app-scoped API key. The authenticated caller must have access to
// the app the agent belongs to. Returns 403 if the key is not app-scoped, and
// 404 if the agent does not exist within the accessible scope.
//
// agent: Agent ID (`agt_...`) whose working memory entries to retrieve.
//
// Returns: Paginated list of working memory entries for the agent.
func (r *AgentWorkingMemoryResource) List(ctx context.Context, agent string, params AgentWorkingMemoryListParams) (*WorkingMemoryEntryListResponse, error) {
	q := url.Values{}
	if params.Page != nil {
		q.Add("page", queryParam(*params.Page))
	}
	if params.PageSize != nil {
		q.Add("page_size", queryParam(*params.PageSize))
	}
	if params.Search != nil {
		q.Add("search", *params.Search)
	}
	return fetch[*WorkingMemoryEntryListResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/agents/" + url.PathEscape(agent) + "/agent_working_memory", Query: q})
}

// Delete: Delete a working memory entry
//
// Permanently deletes a working memory entry from the agent. This action is
// irreversible. Expired entries can also be deleted they are hidden from
// list results but persist until overwritten or deleted.
// Requires an app-scoped API key. The authenticated caller must be able to
// modify the agent that owns the entry. Returns 403 if the key is not
// app-scoped or the caller lacks modify access, and 404 if the agent or entry
// does not exist within the accessible scope.
//
// agent: Agent ID (`agt_...`) whose working memory entries to retrieve.
// entry: Working memory entry ID (`amm_...`) to delete.
//
// Returns: Empty body. Returns HTTP 204 on success.
func (r *AgentWorkingMemoryResource) Delete(ctx context.Context, agent string, entry string) error {
	return r.http.requestVoid(ctx, requestSpec{Method: "DELETE", Path: "/api/v1/agents/" + url.PathEscape(agent) + "/agent_working_memory/" + url.PathEscape(entry)})
}

// Update: Update a working memory entry
//
// Updates the value and/or expiry of an existing working memory entry. Only
// the fields you supply are changed; omitted fields retain their current
// values. The entry `key` cannot be changed after creation delete the entry
// and let the agent (or a future create call) write a new one instead.
// Pass `expires_at` as `null` to remove the expiry so the entry no longer
// expires. Expired entries can still be updated; they stay hidden from list
// results until their expiry is in the future again.
// Requires an app-scoped API key. The authenticated caller must be able to
// modify the agent that owns the entry. Returns 403 if the key is not
// app-scoped or the caller lacks modify access, and 404 if the agent or entry
// does not exist within the accessible scope.
//
// agent: Agent ID (`agt_...`) whose working memory entries to retrieve.
// entry: Working memory entry ID (`amm_...`) to update.
//
// Returns: The updated working memory entry.
func (r *AgentWorkingMemoryResource) Update(ctx context.Context, agent string, entry string, input AgentWorkingMemoryUpdateInput) (*WorkingMemoryEntry, error) {
	return fetch[*WorkingMemoryEntry](r.http, ctx, requestSpec{Method: "PATCH", Path: "/api/v1/agents/" + url.PathEscape(agent) + "/agent_working_memory/" + url.PathEscape(entry), Body: input})
}

